import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals } from '../src/invoices.js';

test('createInvoice creates a draft invoice with product details', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Development (hour)');
});

test('createInvoice rejects unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice rejects invalid date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '07-10-2026',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects non-existent date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects fractional quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'NOPE', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate arguments', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.equal(lines[0].sku, 'DES-HOUR');
  assert.equal(lines[0].qty, 5);
  assert.equal(Object.keys(lines[0]).length, 2);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 100 }), 100);
  assert.equal(lineTotal({ qty: 10, unitPrice: 1 }), 10);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 10, unitPrice: 9500 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 8500 + 10 * 9500);
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.total, 137500);
});

test('invoiceTotals handles single line', () => {
  const invoice = {
    lines: [{ qty: 3, unitPrice: 6000 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 18000);
  assert.equal(totals.total, 18000);
});

test('invoiceTotals handles empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with full invoice from createInvoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const expectedSubtotal = 3 * 8500 + 2 * 9500;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.total, expectedSubtotal);
});

